import{_ as i,o as n,c as r,a2 as t}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Preise und Kosten","description":"","frontmatter":{"order":3,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/02.anleitungen/03.preise-und-kosten.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/anleitungen/preise-und-kosten.md","filePath":"de/adapter/sourceanalytix/anleitungen/preise-und-kosten.md","lastUpdated":null}'),a={name:"de/adapter/sourceanalytix/anleitungen/preise-und-kosten.md"};function s(d,e,l,u,h,c){return n(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="preise-und-kosten" tabindex="-1">Preise und Kosten <a class="header-anchor" href="#preise-und-kosten" aria-label="Permalink to &quot;Preise und Kosten&quot;">​</a></h1><p><a id="costs-recalculated-change-price-change"></a></p><h2 id="werden-berechnete-kosten-neu-berechnet-wenn-ich-den-preis-andere-–-und-wie-andere-ich-ihn-ab-einem-datum" tabindex="-1">Werden berechnete Kosten neu berechnet, wenn ich den Preis ändere – und wie ändere ich ihn ab einem Datum? <a class="header-anchor" href="#werden-berechnete-kosten-neu-berechnet-wenn-ich-den-preis-andere-–-und-wie-andere-ich-ihn-ab-einem-datum" aria-label="Permalink to &quot;Werden berechnete Kosten neu berechnet, wenn ich den Preis ändere – und wie ändere ich ihn ab einem Datum?&quot;">​</a></h2><p>Nicht von selbst. Ein neuer Preis gilt ab dem Datum unter „Gültig ab“, gebuchte Kosten bleiben. Willst du sie neu berechnen, nimm bei der Quelle „Kosten ab Datum neu rechnen“.</p><ol><li>Trage im Tab „Preisdefinitionen“ den neuen „Preis pro Einheit“ oder „Preis pro Monat“ ein.</li><li>Setze „Gültig ab“ auf den Tag, ab dem er gilt. Das Datum darf in der Zukunft liegen.</li><li>Speichere. Ab 0:00 Uhr dieses Tages rechnet SourceAnalytix mit dem neuen Preis.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Gib bei jeder Preisänderung ein neues „Gültig ab“ an. Mit dem alten Datum ersetzt der neue Preis den alten rückwirkend. Der Dialog markiert das mit „Preis geändert, „Gültig ab“ nicht …“, lässt dich aber speichern, damit du Tippfehler korrigieren kannst.</p></div><p>Änderst du nur einen der beiden Preise, bleibt der Verlauf des anderen unberührt. Wechselst du den Anbieter, trag den neuen Preis in derselben Preisdefinition ein, dann bleibt der Preisverlauf zusammen.</p><p>Galt ein Preis schon früher, setze das richtige „Gültig ab“, speichere und wähle bei jeder betroffenen Quelle „Kosten ab Datum neu rechnen“ mit diesem Datum.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#price-definition-structured-categories-base">Wie ist eine Preisdefinition aufgebaut?</a> · <a href="./../referenz/states-und-meldungen#prices-read-written-as-states">Preise als States</a></p><p><a id="include-monthly-base-fee"></a></p><h2 id="wie-rechne-ich-einen-monatlichen-grundpreis-ein" tabindex="-1">Wie rechne ich einen monatlichen Grundpreis ein? <a class="header-anchor" href="#wie-rechne-ich-einen-monatlichen-grundpreis-ein" aria-label="Permalink to &quot;Wie rechne ich einen monatlichen Grundpreis ein?&quot;">​</a></h2><p>Trage den Betrag in der Preisdefinition bei „Preis pro Monat“ ein und schalte bei der Quelle „Grundpreis einrechnen“ ein. Einen Jahresgrundpreis teilst du durch 12.</p><p>SourceAnalytix bucht den vollen Monatsbetrag am Ersten jedes Monats. Am 15. März mit 12 € Grundpreis seit Januar enthalten Tag und Woche also 0 €, der Monat 12 € und Quartal und Jahr je 36 €.</p><p>Den Haken setzt du im Assistenten im Schritt „Preis“ oder später in der Detailansicht unter „Einstellungen“.</p><h3 id="mehrere-quellen-mit-derselben-preisdefinition" tabindex="-1">Mehrere Quellen mit derselben Preisdefinition <a class="header-anchor" href="#mehrere-quellen-mit-derselben-preisdefinition" aria-label="Permalink to &quot;Mehrere Quellen mit derselben Preisdefinition&quot;">​</a></h3><p>Jede Quelle mit „Grundpreis einrechnen“ bucht den vollen Betrag. Gehören mehrere Quellen zu einem Anschluss, etwa Hausstrom und ein Unterzähler, schalte ihn nur bei einer ein. Der Tab „Probleme“ meldet sonst „Grundpreis wird doppelt gebucht“ mit „Hier ausschalten“.</p><p><strong>Siehe auch:</strong> <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#costs-stay-0-not-calculated">Kosten bleiben 0</a></p><p><a id="use-dynamic-electricity-price-tibber"></a></p><h2 id="wie-berucksichtige-ich-einen-dynamischen-strompreis-tibber-awattar" tabindex="-1">Wie berücksichtige ich einen dynamischen Strompreis (Tibber, Awattar)? <a class="header-anchor" href="#wie-berucksichtige-ich-einen-dynamischen-strompreis-tibber-awattar" aria-label="Permalink to &quot;Wie berücksichtige ich einen dynamischen Strompreis (Tibber, Awattar)?&quot;">​</a></h2><p>Stelle in der Preisdefinition die „Preisquelle“ auf „Datenpunkt“ und wähle bei „Preis-Datenpunkt“ den aktuellen Preis. SourceAnalytix bewertet jeden Verbrauch mit dem Preis, der zu dieser Zeit galt.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Der Datenpunkt muss den Preis pro Einheit der Preisdefinition liefern, zum Beispiel <code>0.28</code> für 28 Cent pro kWh. Liefert dein Adapter Cent, rechne ihn vorher um, etwa mit einem Alias.</p></div><p>Ändert sich der Preis zwischen zwei Werten der Quelle, teilt SourceAnalytix den Verbrauch nach der Zeit auf. Je öfter die Quelle sendet, desto genauer. Die laufenden Kosten liegen in <code>sourceanalytix.0.&lt;Gerät&gt;.dynamicCostMemory</code> und überstehen einen Neustart. Hat der Datenpunkt keinen gültigen Wert, rechnet SourceAnalytix mit dem zuletzt eingetragenen festen Preis weiter.</p><p>„Kosten ab Datum neu rechnen“ verteilt den Verbrauch gleichmäßig über die Periode und ist bei stündlichen Preisen nur eine Näherung. Der Dialog weist darauf hin. Nimm die Aktion hier nur, um einen Fehler zu beheben.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#prices-read-written-as-states">Preise als States</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#values-costs-far-too-high">Kosten viel zu hoch</a></p><p><a id="bill-day-night-tariff"></a></p><h2 id="wie-rechne-ich-einen-tag-nachttarif-ht-nt-ab" tabindex="-1">Wie rechne ich einen Tag-/Nachttarif (HT/NT) ab? <a class="header-anchor" href="#wie-rechne-ich-einen-tag-nachttarif-ht-nt-ab" aria-label="Permalink to &quot;Wie rechne ich einen Tag-/Nachttarif (HT/NT) ab?&quot;">​</a></h2><p>Stelle die „Preisquelle“ auf „Tarifumschaltung“. Ein Datenpunkt schaltet dann zwischen zwei Preisen um. Der Verbrauch wird mit dem jeweils gültigen Preis bewertet, aber nicht in HT und NT getrennt.</p><ol><li>Sorge für einen Datenpunkt, der während eines Tarifs zum Beispiel <code>true</code> ist, etwa per Skript oder Zeitplan.</li><li>Trage bei „Preis pro Einheit“ den Preis für „nicht aktiv“ und bei „Aktiver Tarifpreis“ den für „aktiv“ ein.</li><li>Wähle bei „Preis-Datenpunkt“ den Umschalt-Datenpunkt und speichere.</li></ol><p>Ist „Aktiver Auswahlwert“ eingetragen, zum Beispiel <code>NT</code>, gilt nur genau dieser Wert als aktiv. Sonst ist der Datenpunkt aktiv bei <code>true</code>, einer Zahl ungleich 0 oder einem Text außer <code>0</code>, <code>false</code>, <code>off</code>, <code>no</code> und <code>closed</code>.</p><p>Hat dein Zähler eigene Stände für HT und NT, lege lieber zwei Quellen mit festem Preis an. Dann hast du auch den Verbrauch je Tarif.</p><p><a id="assign-prices-create-custom-tariffs"></a></p><h2 id="wie-ordne-ich-preise-zu-und-lege-eigene-tarife-an-z-b-warmepumpe" tabindex="-1">Wie ordne ich Preise zu und lege eigene Tarife an (z. B. Wärmepumpe)? <a class="header-anchor" href="#wie-ordne-ich-preise-zu-und-lege-eigene-tarife-an-z-b-warmepumpe" aria-label="Permalink to &quot;Wie ordne ich Preise zu und lege eigene Tarife an (z. B. Wärmepumpe)?&quot;">​</a></h2><p>Jede Quelle hat genau eine Preisdefinition. Für einen eigenen Tarif, etwa die Wärmepumpe, legst du im Tab „Preisdefinitionen“ eine weitere Zeile an und wählst sie bei der Quelle.</p><ol><li>Füge im Tab „Preisdefinitionen“ eine Zeile hinzu.</li><li>Gib eine eindeutige „Kategorie“ ein, zum Beispiel <code>Waermepumpe</code>. Leere oder doppelte Namen markiert die Seite mit „Kategorie leer oder doppelt vergeben“.</li><li>Wähle „Kostenart“, „Einheit“ und „Preisquelle“, trage den Preis ein und speichere.</li><li>Wähle den Tarif im Assistenten im Schritt „Preis“ oder in der Detailansicht der Quelle bei „Preisdefinition“.</li></ol><p>Der Preis gilt pro Einheit der Preisdefinition. Für Kosten pro Kilometer wählst du <code>km</code>, für einen Preis pro Stück <code>piece</code>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Benenne eine Kategorie nicht um, solange Quellen sie nutzen. Die Quellen rechnen dann nicht weiter, der Tab „Probleme“ meldet „Preisdefinition gibt es nicht mehr“. Wähle danach bei jeder Quelle die neue Preisdefinition.</p></div><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#price-definition-structured-categories-base">Wie ist eine Preisdefinition aufgebaut?</a> · <a href="./quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Welche Einheit am Datenpunkt?</a></p>',37)])])}const m=i(a,[["render",s]]);export{p as __pageData,m as default};
